// Filter endpoints not seen in 30+ days
const STALE_DAYS = 30;
const cutoff = new Date(Date.now() - STALE_DAYS * 24 * 60 * 60 * 1000);

const stale = $input.all().filter(i => {
  const lastSeen = new Date(i.json.lastSeen || i.json.lastContact || 0);
  return lastSeen < cutoff;
});

if (stale.length === 0) {
  return [{ json: { hasStale: false, summary: `No endpoints inactive for ${STALE_DAYS}+ days.` } }];
}

return stale.map(i => ({
  json: {
    hasStale: true,
    displayName: i.json.displayName || i.json.hostName || 'Unknown',
    lastSeen: i.json.lastSeen || i.json.lastContact || 'Never',
    logicalGroupId: i.json.logicalGroupId || '-',
    endpointType: i.json.endpointType || '-',
    primaryUser: i.json.primaryUser || '-',
  }
}));

// Aggregate stale endpoints by group and build summary
const items = $input.all();
const byGroup = {};
for (const i of items) {
  const group = i.json.logicalGroupId || 'Unassigned';
  if (!byGroup[group]) byGroup[group] = [];
  byGroup[group].push(i.json);
}

const groupSummary = Object.entries(byGroup).map(([group, endpoints]) => ({
  group,
  count: endpoints.length,
  endpoints: endpoints.map(e => `${e.displayName} (last: ${e.lastSeen})`).join(', '),
}));

return [{ json: {
  totalStale: items.length,
  groups: groupSummary,
  staleEndpoints: items.map(i => i.json),
} }];
